#include <omp.h>

/* Vector x contains values between 0 and 100, inclusive. Count the number of
   values in [0,10), [10, 20), [20, 30), ... and store the counts in `bins`.
   Use OpenMP to compute in parallel.
   Example:

   input: [7, 32, 95, 12, 39, 32, 11, 71, 70, 66]
   output: [1, 2, 0, 3, 0, 0, 1, 2, 0, 1]
*/
void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {

```cpp
#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);
    size_t n = x.size();
    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < n; ++i) {
        double val = x[i];
        size_t idx = static_cast<size_t>(val / 10.0);
        if (idx >= 10) idx = 9;               // clamp 100 to last bin
        #pragma omp atomic update
        bins[idx]++;                          // count in the appropriate bin
    }
}
